  "number[]              // 숫자 배열\nstring[]              // 문자열 배열\nboolean[]             // 불리언 배열\n{ name: string }[]    // 객체 배열\n(string | number)[]   // 문자열 또는 숫자가 섞인 배열 (유니온은 괄호로 묶는다)": "<span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">number</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">[]              </span><span style=\"--shiki-light:#008000;--shiki-dark:#6A9955\">// 숫자 배열</span><br><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">string</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">[]              </span><span style=\"--shiki-light:#008000;--shiki-dark:#6A9955\">// 문자열 배열</span><br><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">boolean</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">[]             </span><span style=\"--shiki-light:#008000;--shiki-dark:#6A9955\">// 불리언 배열</span><br><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">{ </span><span style=\"--shiki-light:#000000;--shiki-dark:#C8C8C8\">name</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">: </span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">string</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\"> }[]    </span><span style=\"--shiki-light:#008000;--shiki-dark:#6A9955\">// 객체 배열</span><br><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">(</span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">string</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\"> | </span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">number</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">)[]   </span><span style=\"--shiki-light:#008000;--shiki-dark:#6A9955\">// 문자열 또는 숫자가 섞인 배열 (유니온은 괄호로 묶는다)</span>",
